<?php

namespace App\Exceptions\Cycle;

use App\Exceptions\DomainException;

/**
 * The routine's next cycle is already being generated by queued jobs. HTTP 409
 * — the client should keep polling the routine instead of asking again.
 */
final class CycleGenerationInProgressException extends DomainException
{
    protected string $errorCode = 'CYCLE_GENERATION_IN_PROGRESS';

    public function __construct()
    {
        parent::__construct('The next cycle is already being generated. Check back in a few minutes.');
    }
}
